    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2023 Ordinary Level — © State Examinations Commission.",
    id: "eng-2023-ol-q2-d-i", topicId: "eng-1-2", conceptId: "term-alloy",
