    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2026 Ordinary Level — © State Examinations Commission.",
    id: "eng-2026-ol-q3-d-i", topicId: "eng-3-14", conceptId: "malleability-or-ways-robotic-technology-can",
    section: "A", questionRef: "2026 OL Q3(d)(i)",
